// allSettled waits for every task, including the ones that reject
const results = await Promise.allSettled([
  fetch("https://example.com/a"),
  fetch("https://example.com/b"),
]);

for (const result of results) {
  console.log(result.status);   // "fulfilled" or "rejected"
}

// race settles with whichever promise gets there first
const winner = await Promise.race([
  fetch("https://example.com/slow-report"),
  new Promise((resolve) => setTimeout(() => resolve("gave up"), 2000)),
]);

console.log(winner);

async function loadOrder(id) {
  const response = await fetch(`https://example.com/orders/${id}`);
  if (!response.ok) {
    throw new Error(`order ${id} failed with ${response.status}`);
  }
  return response.json();
}

// One try block covers every await inside it
try {
  const order = await loadOrder("ord_1042");
  console.log(order.item);
} catch (error) {
  console.error(error.message);
}

// Waiting one call at a time costs three round trips
const first = await fetch("https://example.com/1");
const second = await fetch("https://example.com/2");
const third = await fetch("https://example.com/3");

// Starting all three at once costs one
const [a, b, c] = await Promise.all([
  fetch("https://example.com/1"),
  fetch("https://example.com/2"),
  fetch("https://example.com/3"),
]);

console.log(first.status, second.status, third.status, a.status, b.status, c.status);

// AbortSignal.timeout rejects with a TimeoutError after 5 seconds
try {
  const response = await fetch("https://example.com/report", {
    signal: AbortSignal.timeout(5000),
  });
  console.log(response.status);
} catch (error) {
  if (error.name === "TimeoutError") console.error("report took too long");
  else throw error;
}

