import { EventEmitter } from "node:events";

class JobQueue extends EventEmitter {
  #jobs = [];

  add(name) {
    this.#jobs.push(name);
    this.emit("added", name);
  }
}

const queue = new JobQueue();
queue.on("added", (name) => console.log(`${name} queued`));
